  "resolution": [
    "No poema do árcade Silva Alvarenga, Vênus perde a cinta e roga aos mares que lhe devolvam o objeto: os mares deem a cinta a Vênus. O termo “Vênus” é objeto indireto do verbo dar, por isso deve ser substituído pelo pronome “lhe”; “a cinta” é objeto direto do verbo dar e deve ser substituído pelo pronome “a”. A contração de “lhe”+ “a” gera o pronome “lha” que funciona sintaticamente como objeto direto e indireto."
  ],
  "resolutionMatched": true,
  "correctionOrigin": "official",
