  "statement": "Para responder às questões de 07 a 10, leia o trecho de uma crônica de Machado de Assis, publicada originalmente em 16.06.1878.\n\nEstrugiram 1 os últimos foguetes de Santo Antônio; não tarda chegar a vez de S. João e de S. Pedro. [...] Indague quem quiser o motivo histórico deste foguetear os três santos, uso que herdamos dos nossos maiores; a realidade é que, não obstante o ceticismo do tempo, muita e muita dezena de anos há de correr, primeiro que o povo perca os seus antigos amores. Nestas noites abençoadas é que as crendices sãs abrem todas as velas. As consultas, as sortes, os ovos guardados em água, e outras sublimes ridicularias 2, ria-se delas quem quiser; eu vejo-as com respeito, com simpatia, e se alguma coisa me molestam é por eu não as saber já praticar. [...]\n\nOs dias passam, e os meses, e os anos, e as situações políticas, e as gerações e os sentimentos, e as ideias. Cada olimpíada 3 traz nas mãos uma nova andaina 4 do tempo. [...]\n\nDuas coisas, entretanto, perduram no meio da instabilidade universal: 1o a constância da polícia, que todos os anos declara editalmente ser proibido queimar fogos, por ocasião das festas de S. João e seus comensais; 2o a disposição do povo em desobedecer às ordens da polícia. A proibição não é simples vontade do chefe; é uma postura municipal de 1856. Anualmente aparece o mesmo edital, escrito com os mesmos termos; o chefe rubrica essa chapa inofensiva, que é impressa, lida e desrespeitada. Da tenacidade com que a polícia proíbe, e da teimosia com que o povo infringe a proibição, fica um resíduo comum: o trecho impresso e os fogos queimados.\n\n(Machado de Assis. Notas semanais, 2008.)\n\n1 estrugir: soar ou vibrar fortemente.\n\n2 ridicularia: coisa mínima e sem importância; insignificância.\n\n3 olimpíada: período de quatro anos.\n\n4 andaina: veste.\n\n“a realidade é que, <u>não obstante o ceticismo do tempo</u>, muita e muita dezena de anos há de correr, primeiro que o povo perca os seus antigos amores.” (1o parágrafo)\n\nNo contexto em que se insere, o trecho sublinhado expressa ideia de",
