  "n": 22,
  "subject": "História",
  "content": "Idade Média e visão de mundo",
  "detail": "Explicação religiosa para fome e eventos climáticos",
  "difficulty": "Média",
  "statement": "Analise o relato escrito por um monge no século XI.\n\n[...] a fome começou a alastrar-se por toda a superfície da Terra, e chegou-se a temer o quase total desaparecimento do gênero humano. As condições atmosféricas, com efeito, a tal ponto iam contra o curso normal das estações que o tempo nunca se mostrava propício às semeaduras e, sobretudo por causa das inundações, jamais se apresentava favorável às colheitas. Parecia que os elementos estavam lutando entre si, mas não havia dúvidas de que se punia assim o orgulho da humanidade.\n\n(Raoul Glaber. Histoires. Apud: Georges Duby.\n\nA Europa na Idade Média, 1988. Adaptado.)\n\nO monge atribui a temporada de fome ocorrida naquele período",
  "blockTypes": [
    "prose",
    "prose",
    "prose",
    "prose",
    "command"
  ],
  "alternatives": [
    "ao controle humano dos movimentos da natureza.",
    "ao aumento da exploração dos servos pelos senhores feudais.",
    "à insuficiência de conhecimento de técnicas de plantio.",
    "a eventos climáticos provocados pela cólera divina.",
    "a alterações da natureza geradas pela exploração da terra."
  ],
  "answer": "D",
  "annulled": false,
  "annulmentNoValidAnswer": false,
  "resolution": [
    "Eventos climáticos ou alterações nos ciclos da natureza eram de difícil compreensão pelas pessoas em períodos como o da Idade Média ou anteriores à Revolução Científica do início da Idade Moderna. Assim, ao não entender os fenômenos como naturais, estes eram compreendidos como um castigo divino por conta de ações e pecados da humanidade."
  ],
  "resolutionMatched": true,
  "correctionOrigin": "official",
  "sourceSha256": "49ece631ef5178f62ce5fcc434f2cb6c98b66e8c625cfa46ab89ae6484731d5c",
