  "shortAlternatives": [
    "era exercido exclusivamente por pessoas livres que podiam circular com autonomia pelas diversas áreas da colônia.",
    "dependia de suprimentos provenientes das regiões distantes que enviavam mercadorias às Minas Gerais.",
    "facilitava o abastecimento interno numa região em que os moradores viviam espalhados pelas vilas e montanhas.",
    "era duramente tributado para que os lucros alcançados se concentrassem nas mãos dos representantes da Coroa portuguesa.",
    "concorria com o comércio regular e estável que era o único capaz de atender às necessidades da população das Minas Gerais."
  ],
  "analyses": [
    "Incorreta. O abastecimento das Gerais não dependia unicamente de frotas mercantis marítimas, pois a capitania era interiorana.",
    "Incorreta. O cultivo de subsistência era proibido apenas temporariamente no auge do primeiro surto aurífero, logo cedendo espaço ao comércio interno.",
    "Correta. Em Minas Gerais, a atividade mineradora concentrou volumosa população urbana desprovida de autossuficiência agrícola, impulsionando um dinâmico mercado interno colonial de comércio ambulante e tropas de mulas para garantir o abastecimento de gêneros.",
    "Incorreta. A metrópole não logrou controlar de forma estanque todo o trânsito de alimentos entre as capitanias.",
    "Incorreta. O comércio interno não era operado apenas por escrivães públicos da Coroa."
  ],
  "resolutionSource": "Objetivo — resolução comentada, usada como referência editorial",
