    "à queda na importação de urânio, imprescindível para a produção de energia nuclear.",
    "à baixa eficiência energética brasileira, majoritariamente movida a óleo combustível.",
    "à forte intensidade do período de seca, quando a geração de energia hidrelétrica diminui.",
