  "subject": "Biologia",
  "content": "Fisiologia humana",
  "detail": "Receptores opioides e sinapse neural",
  "difficulty": "Média",
  "statement": "O fentanil é um potente opioide sintético que atua no sistema central humano como anestésico. Uma vez que atinge o cérebro, o fentanil interage com os receptores opioides, facilitando a liberação de dopamina, anulando a dor, gerando sensação de prazer, de calma e a redução da ansiedade. O tronco cerebral, que controla a função respiratória, também possui receptores opioides. E, quando eles são inundados com fentanil, “você pode parar de respirar, mesmo se estiver consciente”, explica Daniel Sitar, professor da Faculdade de Ciências da Saúde da Universidade de Manitoba, no Canadá.\n\n(https://g1.globo.com. Adaptado.)\n\nDe acordo com o excerto, o fentanil atua",
  "blockTypes": [
    "prose",
    "source",
    "command"
  ],
  "alternatives": [
    "nos axônios dos neurônios ao inibir o transporte de neurotransmissores ao longo dessas estruturas celulares.",
    "nas terminações axoniais dos neurônios ao bloquear a liberação de neurotransmissores pela membrana da célula.",
    "na sinapse neural ao interagir com as proteínas de membrana presentes na superfície externa dos dendritos nos neurônios.",
    "no núcleo do neurônio ao inibir a expressão do gene responsável pela síntese de neurotransmissores.",
    "na bainha de mielina dos neurônios ao interromper a condução dos impulsos nervosos pelo bloqueio de receptores nos axônios."
  ],
  "answer": "C",
  "annulled": false,
  "annulmentNoValidAnswer": false,
  "resolution": [
    "De acordo com o texto, o fentanil tem uma atuação análoga à dos neurotransmissores do sistema nervoso. Logo, ele atua na fenda sináptica e se acopla a receptores presentes na face externa da membrana dos dendritos do neurônio."
  ],
  "resolutionMatched": true,
  "correctionOrigin": "official",
  "sourceSha256": "49ece631ef5178f62ce5fcc434f2cb6c98b66e8c625cfa46ab89ae6484731d5c",
  "officialVersion": 3,
  "images": [],
  "alternativeImages": {},
  "alternativeRender": [
    "text",
    "text",
    "text",
    "text",
    "text"
  ],
  "shortAlternatives": [
    "nos axônios dos neurônios ao inibir o transporte de neurotransmissores ao longo dessas estruturas celulares.",
    "nas terminações axoniais dos neurônios ao bloquear a liberação de neurotransmissores pela membrana da célula.",
    "na sinapse neural ao interagir com as proteínas de membrana presentes na superfície externa dos dendritos nos neurônios.",
    "no núcleo do neurônio ao inibir a expressão do gene responsável pela síntese de neurotransmissores.",
    "na bainha de mielina dos neurônios ao interromper a condução dos impulsos nervosos pelo bloqueio de receptores nos axônios."
  ],
  "analyses": [
    "Incorreta. O fentanil atua no sistema nervoso central e periférico e não no epitélio renal distal.",
    "Incorreta. Não é um anestésico inalatório volátil de absorção alveolar.",
    "Correta. O fentanil é um fármaco opioide sintético de extrema potência analgésica que se liga com alta afinidade a receptores opioides (especialmente receptores $\\mu$) nos neurônios do sistema nervoso, bloqueando a transmissão sináptica da dor e provocando depressão respiratória em doses excessivas.",
    "Incorreta. Não atua estimulando receptores adrenérgicos causadores de hipertensão e taquicardia.",
    "Incorreta. Não destrói a bainha de mielina dos axônios motores periféricos."
  ],
