  "difficulty": "Média",
  "statement": "O heredograma apresenta indivíduos que têm informações sobre a tipagem sanguínea para o fator Rh. Os homens destacados (II-1 e II-5) apresentaram eritroblastose fetal ao nascer, e nenhuma mulher desse heredograma recebeu imunizante anti-Rh após os nascimentos dos filhos.",
