  "statement": "Em um experimento de química, dois líquidos, 1 e 2, foram adicionados a um tubo de ensaio, conforme representado na figura.\n\nNa tabela são apresentadas algumas propriedades de substâncias que são líquidas em temperatura ambiente.",
