  "annulled": false,
  "annulmentNoValidAnswer": false,
  "resolution": [
    "Os líquidos formam duas fases porque são imiscíveis. A fase superior é a água, polar e menos densa que o tetracloreto de carbono; a fase inferior é o tetracloreto de carbono, apolar e de densidade $1{,}59\\ \\mathrm{g/cm^3}$. Logo, os líquidos 1 e 2 são, respectivamente, água e tetracloreto de carbono."
  ],
  "resolutionMatched": true,
