  "difficulty": "Média",
  "statement": "Em um laboratório químico existem três cilindros de gases com iguais capacidades volumétricas, conforme mostra a figura.\n\nNos cilindros, estão contidos, separadamente, os gases $\\mathrm{SO}_{2}$, $\\mathrm{O}_{3}$ e $\\mathrm{O}_{2}$ sob a mesma condição de temperatura e pressão.",
  "blockTypes": [
    "prose"
  ],
  "alternatives": [
    "$m_{\\mathrm{SO}_2}=m_{\\mathrm{O}_3}=m_{\\mathrm{O}_2}$",
    "$m_{\\mathrm{SO}_2}>m_{\\mathrm{O}_3}<m_{\\mathrm{O}_2}$",
    "$m_{\\mathrm{SO}_2}>m_{\\mathrm{O}_3}>m_{\\mathrm{O}_2}$",
    "$m_{\\mathrm{SO}_2}=m_{\\mathrm{O}_3}>m_{\\mathrm{O}_2}$",
    "$m_{\\mathrm{SO}_2}<m_{\\mathrm{O}_3}>m_{\\mathrm{O}_2}$"
  ],
  "answer": "C",
  "annulled": false,
  "annulmentNoValidAnswer": false,
  "resolution": [
    "Nas mesmas condições de temperatura e pressão, volumes iguais contêm a mesma quantidade $n$ de gás. Como $m=nM$ e $M_{\\mathrm{SO}_2}=64$, $M_{\\mathrm{O}_3}=48$ e $M_{\\mathrm{O}_2}=32\\ \\mathrm{g/mol}$, tem-se $m_{\\mathrm{SO}_2}>m_{\\mathrm{O}_3}>m_{\\mathrm{O}_2}$."
  ],
  "resolutionMatched": true,
  "correctionOrigin": "official",
  "sourceSha256": "49ece631ef5178f62ce5fcc434f2cb6c98b66e8c625cfa46ab89ae6484731d5c",
  "officialVersion": 3,
