    "Correta. O dióxido de enxofre ($\\mathrm{SO}_2$) emitido pela queima de combustíveis fósseis é um dos principais causadores da chuva ácida; na atmosfera, oxida-se a trióxido de enxofre ($\\mathrm{SO}_3$) e reage com as gotículas de água nas nuvens gerando ácido sulfúrico ($\\mathrm{H}_2\\mathrm{SO}_4$), um ácido forte que reduz criticamente o pH das precipitações.",
    "Incorreta. Não gera ácido fluorídrico por hidratação condensada."
