  "subject": "Química",
  "content": "Metodologia científica",
  "detail": "Experimentação após formulação de hipótese",
  "difficulty": "Média",
  "statement": "O método científico é uma abordagem sistemática utilizada para a investigação de fenômenos e aquisição de novos conhecimentos. Ele baseia-se em observações rigorosas e controladas, a partir das quais suposições são constantemente testadas por meio de experimentação e análise crítica.\n\nNo contexto do método científico, o que deve ocorrer, sequencialmente, após a formulação de uma hipótese é a",
  "blockTypes": [
    "prose",
    "command"
  ],
  "alternatives": [
    "observação de fenômenos naturais.",
    "publicação dos resultados em revistas científicas.",
    "realização de experimentos e coleta de dados.",
    "definição do problema a ser investigado.",
    "revisão da literatura científica existente."
  ],
  "answer": "C",
  "annulled": false,
  "annulmentNoValidAnswer": false,
  "resolution": [
    "Depois de formular uma hipótese, o pesquisador deve testá-la por experimentos e coleta de dados, seguidos de análise. A etapa imediata pedida é, portanto, a da alternativa C."
  ],
  "resolutionMatched": true,
  "correctionOrigin": "official",
