    "Correta. Para sólidos isotrópicos homogêneos, o coeficiente de dilatação volumétrica é aproximadamente o triplo do coeficiente de dilatação linear ($\\gamma = 3\\alpha$). Consequentemente, a variação percentual relativa de uma dimensão linear (como o diâmetro) é um terço da variação percentual de volume sofrida pelo corpo: $\\frac{\\Delta d}{d_0} = \\frac{1}{3} \\cdot \\frac{\\Delta V}{V_0} = \\frac{0{,}27\\%}{3} = 0{,}09\\%$.",
