  "detail": "Energia do fóton e frequência mínima",
  "difficulty": "Média",
  "statement": "O transporte de energia por meio de radiação eletromagnética ocorre na forma de “partículas” de energia, denominadas fótons. A quantidade de energia de cada fóton, $E_F$, é dada pela expressão $E_F = h \\cdot f$, sendo $f$ a frequência da radiação e $h$ a constante de Planck, cujo valor é $6{,}6 \\times 10^{-34}\\ \\mathrm{J\\cdot s}$. Ao incidir na superfície de certos materiais, esses fótons podem produzir a emissão de elétrons por essa superfície, mas, para que essa emissão ocorra, é necessário que o fóton transporte uma quantidade mínima de energia, a qual depende do material da superfície. Para uma superfície de potássio, a quantidade mínima de energia necessária para ocorrer a emissão de um elétron é de $3{,}5 \\times 10^{-19}\\ \\mathrm{J}$.\n\nA tabela mostra a frequência de cinco cores de luz que incidem em uma superfície de potássio:",
  "blockTypes": [
    "prose",
    "prose",
    "prose",
    "command"
  ],
  "alternatives": [
    "violeta, azul, verde e laranja.",
    "violeta e azul.",
    "violeta, azul e verde.",
    "verde, laranja e vermelha.",
    "laranja e vermelha."
  ],
  "answer": "C",
  "annulled": false,
  "annulmentNoValidAnswer": false,
  "resolution": [
    "A frequência mínima satisfaz $hf>3{,}5\\times10^{-19}\\ \\mathrm{J}$. Assim, $f>\\frac{3{,}5\\times10^{-19}}{6{,}6\\times10^{-34}}\\approx5{,}3\\times10^{14}\\ \\mathrm{Hz}$. Pela tabela, somente verde, azul e violeta superam essa frequência, alternativa C."
  ],
  "resolutionMatched": true,
  "correctionOrigin": "official",
  "sourceSha256": "49ece631ef5178f62ce5fcc434f2cb6c98b66e8c625cfa46ab89ae6484731d5c",
