  "difficulty": "Média",
  "statement": "A tabela indica a correspondência entre temperaturas nas escalas termométricas A, B e C. Sabe-se que $t_B = mt_A + n$ e $t_C = pt_B + q$, com $m$, $n$, $p$ e $q$ sendo números reais:",
