  "shortAlternatives": [
    "15,0.",
    "22,5.",
    "12,5.",
    "36,0.",
    "18,5."
  ],
  "analyses": [
    "Incorreta. Calcula apenas a meia-vida inicial sem avaliar a diferença no tempo de 150 unidades.",
    "Correta. A lei exponencial do decaimento radioativo da substância é dada por $f(t) = 60 \\cdot 2^{-t/50}$. Para $t = 50$, temos $f(50) = 60 \\cdot 2^{-50/50} = 60 \\cdot 2^{-1} = 30$. Para $t = 150$, temos $f(150) = 60 \\cdot 2^{-150/50} = 60 \\cdot 2^{-3} = \\frac{60}{8} = 7{,}5$. A diferença pedida entre esses dois valores é $f(50) - f(150) = 30 - 7{,}5 = 22{,}5$ unidades.",
    "Incorreta. Erro na potenciação com expoente negativo fracionário.",
    "Incorreta. Considera decaimento linear aditivo constante.",
    "Incorreta. Subestima o resíduo da amostra radioativa remanescente."
  ],
  "resolutionSource": "Objetivo — resolução comentada, usada como referência editorial",
