  "difficulty": "Média",
  "statement": "O lucro $L(x)$, em reais, de uma empresa em função do número x de empregados que nela trabalham é dado por $L(x)=-x^2+820x$. De acordo com tal modelo, o lucro máximo que essa empresa pode obter é igual a",
