      "expected": "A fórmula estrutural do dímero é $\\mathrm{Cl}-\\mathrm{O}-\\mathrm{O}-\\mathrm{Cl}$. (1 ponto) Para $2\\mathrm{ClO}(g)\\rightleftharpoons(\\mathrm{ClO})_{2}(g)$, a constante é $K_c=\\frac{[(\\mathrm{ClO})_{2}]}{[\\mathrm{ClO}]^2}$; também foi aceita a expressão correspondente de $K_p$. (1 ponto)",
