  "detail": "Proibição de livros na escola: censura ou proteção da infância e da juventude?",
  "difficulty": "Média",
  "statement": "Texto 1\n\nNo início de março de 2024, os governos estaduais de Mato Grosso do Sul, Goiás e Paraná orientaram as respectivas secretarias de educação que retirassem dos acervos das escolas o livro O Avesso da Pele, vencedor do prêmio Jabuti de 2021, do autor Jefferson Tenório, sob o argumento de que a obra contém expressões impróprias para menores de 18 anos. A iniciativa foi recebida com uma saraivada de críticas e, após algumas semanas, os três governos estaduais reverteram suas decisões. A controvérsia, porém, somou-se a outros episódios de tentativa de proibição registrados no país nos últimos anos e que afetaram, principalmente, obras destinadas ao público infantojuvenil.\n\n(Marcos do Amaral Jorge. “Polêmicas envolvendo literatura infantojuvenil, que incluem cancelamentos e banimento de livros em escolas, já preocupam editoras”. https://jornal.unesp.br, 23.05.2024. Adaptado.)\n\nTexto 2\n\nAs entidades responsáveis pela produção e distribuição de livros no Brasil repudiam veementemente a censura a livros. A recente censura do Menino Marrom, de Ziraldo, nas escolas municipais de Conselheiro Lafaiete (MG), e o recolhimento da obra Meninas Sonhadoras, Mulheres Cientistas, da juíza Flávia Martins de Carvalho, das salas de leitura da rede municipal pela prefeitura de São José dos Campos (SP), são atos inaceitáveis que configuram um claro ataque à liberdade de expressão, pilar fundamental para a democracia e o desenvolvimento de um país.\n\nA liberdade de expressão é um direito fundamental garantido pela Constituição Federal do Brasil, em seu artigo 5º. A censura de livros, além de violar esse direito, também prejudica o acesso ao conhecimento e à cultura.\n\nZiraldo é um autor consagrado, que contribuiu significativamente, por décadas, para a consolidação da literatura infantil em nosso país, conquistando milhões de leitores. Sua obra Menino Marrom aborda temas fundamentais, como diversidade e inclusão, que são cruciais para a formação de uma sociedade mais justa e igualitária. Da mesma forma, a obra Meninas Sonhadoras, Mulheres Cientistas, da juíza Flávia Martins de Carvalho, destaca a importância de promover a igualdade de gênero e incentivar meninas a perseguirem carreiras na ciência. A censura desta obra impede que jovens leitoras tenham acesso a histórias inspiradoras que podem influenciar positivamente suas vidas e escolhas profissionais.\n\n(“Nota de repúdio à censura de livros”. https://cbl.org.br, 21.06.2024. Adaptado.)\n\nTexto 3\n\nAo denunciar o uso do livro O Avesso da Pele por conter vocabulários considerados de baixo nível para alunos adolescentes, o posicionamento da diretora escolar Janaina Venzon recebeu apoio de um deputado estadual que declarou: “Nosso compromisso é com a proteção da infância, assegurando que os jovens não sejam expostos a conteúdos inadequados a sua idade, incluindo linguagem vulgar ou temas sexuais em materiais didáticos”.\n\nO deputado salientou que a preocupação não reside no conteúdo intrínseco da obra, como o racismo abordado em O Avesso da Pele, mas sim na sua aplicação de linguajar impróprio no ambiente escolar. “Tal postura não constitui censura, mas uma defesa pelo ensino que respeite as fases de desenvolvimento”, esclareceu. “Acredito que esta é uma discussão necessária. Certamente irá fomentar debates sobre o papel dos pais, educadores e parlamentares a respeito da proteção da infância e da juventude contra conteúdos considerados inadequados para sua faixa etária”, reitera o deputado.\n\n(Leonardo Nunes. “Deputado defende limites para conteúdos didáticos”. ww4.al.rs.gov.br, 04.03.2024. Adaptado.)\n\nCom base nos textos apresentados e em seus próprios conhecimentos, escreva um texto dissertativo-argumentativo, empregando a norma-padrão da língua portuguesa, sobre o tema:\n\nProibição de livros na escola: censura ou proteção da infância e da juventude?",
